VAR
    Overload_Timer : TON;
END_VAR

Overload_Timer(IN := (Motor_Current > 47.725) AND Motor_Running, PT := T#500MS);

Overload_Alarm := (Motor_Current > 47.725);

IF (Motor_Current > 62.25) OR (Motor_Winding_Temp > 145.0) OR Overload_Timer.Q THEN
    Motor_Stop := TRUE;
END_IF;

IF Fault_Reset THEN
    Motor_Stop := FALSE;
END_IF;

